INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(8,'chris','2026-08-24','Gym: treadmill and weights',35,298,'2026-08-24 14:28:01',replace('Gym from 6:03 to 6:38.\nTreadmill warm-up: 10 minutes, 0.42 mi, 1 percent incline.\nBar squats: 4 sets, empty bar. Reps per set were 6-8.\nI moved to hammer strength arm workout: 25 lbs., 5 sets of 10 reps, biceps, and varied arm rowing movements.\nI did a treadmill cool-down: 8 minutes, 0.31 mi, 3 percent incline.\nTotal treadmill was 18 minutes, 0.73 mi.\nMy strength training was approximately 17 minutes.\nTotal workout: 35 minutes.','\n',char(10)));
