INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(10,'chris','2026-08-25','Light cardio and strength active recovery',13,105,'2026-08-25 12:15:12','Light mixed cardio and strength workout lasting 13 minutes. Approximately 5 minutes walking on treadmill at about 3.5 mph with 2% incline, stopped early due to treadmill feel. Followed by approximately 7-8 minutes of light exercise: various arm exercises using 5 lb dumbbells, very light wall-supported knee bends for sore thighs, and some seated couch squats / sit-to-stand movements. Overall intensity was light as an active recovery from yesterday''s squat workout.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(11,'chris','2026-08-25','Treadmill walking',35,268,'2026-08-25 17:35:43','Treadmill walking on August 25, 2026. Duration: 35 minutes. Intensity: light to moderate. Distance: 1.27 miles. First 30 minutes at normal walking pace. Final 5 minutes cooldown at 0.5 mph. Overall average speed: approximately 2.18 mph. Treadmill display estimated 237 calories burned.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(12,'chris','2026-08-26','Treadmill Walking',35,284,'2026-08-26 11:59:00','Treadmill Walking -- August 26, 2026. Duration: 35 minutes. Distance: 1.48 miles. Average speed: about 2.54 mph. Average pace: about 23:39 per mile. Incline: manually varied between 1% and 3%. Ending incline: 1%. Calories burned: 293. Intensity: light to moderate. Steady treadmill walking session with incline varied throughout the workout for added intensity.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(13,'chris','2026-08-26','Dumbbell arm exercises',10,81,'2026-08-26 20:45:05','Ten minutes of activity using dumbbell weights with various arm exercises. For my breaks, I would just switch to the other arm or switch to a different exercise. It was ten minutes.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(14,'chris','2026-08-26','Light recreational swimming',20,163,'2026-08-26 23:38:14','Approximately 20 minutes in the pool playing, splashing around, moving through the water, and casually swimming. This was recreational pool activity rather than continuous lap swimming or a structured swim workout.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(15,'chris','2026-08-27','Hot Yoga',50,522,'2026-08-27 23:33:04','Hot Yoga - August 27, 2026. Duration: 50 minutes. Time: 5:30-6:20 PM. Hot yoga class in an approximately 80 degrees F room. Full-body yoga involving sustained stretching, balance, mobility, core work, bodyweight holds, and repeated poses. Moderate-to-vigorous intensity with significant sweating, noticeably elevated heart rate, and substantial muscular fatigue/soreness. Very challenging session and considerably more intense than light or restorative yoga.');
INSERT INTO "exercise_entries" ("id","owner","exercised_on","activity","minutes","calories","created_at","comments") VALUES(16,'chris','2026-08-28','Treadmill walking',35,273,'2026-08-28 11:51:01','Treadmill walking on August 28, 2026. Duration: 35 minutes. Intensity: light to moderate. Total distance: 1.55 miles. Average speed: 2.7 mph. Total feet climbed: 129 ft. First 30 minutes before cooldown: 1.48 miles. Final 5 minutes were cooldown. Treadmill-reported calories: 300.');
