CREATE TABLE `exercise_library` (
  `id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
  -- NULL for shared/system exercises, a profile for one someone adds later.
  `owner` text,
  -- Stable import key. Re-running the seed matches on this rather than on the
  -- display name, so renaming an exercise never duplicates it.
  `slug` text NOT NULL,
  `name` text NOT NULL,
  `category` text,
  `primary_muscle_group` text,
  `equipment_type` text,
  -- reps_weight | reps_bodyweight | duration | distance_duration | class
  `measurement_type` text NOT NULL DEFAULT 'reps_weight',
  `description` text,
  `video_url` text,
  `source_url` text,
  `is_system` integer NOT NULL DEFAULT 0,
  `is_active` integer NOT NULL DEFAULT 1,
  `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CHECK (`measurement_type` IN ('reps_weight','reps_bodyweight','duration','distance_duration','class'))
);
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(1,NULL,'kettlebell-goblet-squat','Kettlebell Goblet Squat','strength','Legs','Kettlebell','reps_weight','Select a kettlebell and hold it by the handles at chest height. Stand with your feet shoulder-width apart and toes slightly turned out. Keep your chest tall and core engaged as you begin by sitting your hips back. Lower into a squat, keeping your elbows inside your knees and your weight in your heels. Drive through your heels to return to standing, squeezing your glutes at the top.','https://www.youtube.com/watch?v=Op6aBo7diZA','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(2,NULL,'trx-underhand-row','TRX Underhand Row','strength','Back','TRX','reps_bodyweight','Adjust the TRX straps to mid-length and lean back to create your desired resistance level. Grip the handles with palms facing up and keep your body in a straight line from head to heels. Start with your arms fully extended and shoulders pulled down away from your ears. Pull your chest toward the handles, keeping your elbows close to your sides. Slowly extend your arms to return to the starting position.','https://www.youtube.com/watch?v=kzvQ2c0Odzw','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(3,NULL,'box-elevated-push-up','Box-Elevated Push-Up','strength','Chest','Box or bench','reps_bodyweight','Place your hands on a box or bench (use a higher surface to decrease difficulty). Position your body in a straight plank with hands under shoulders and core engaged. Begin by bending your elbows and lowering your chest toward the box while maintaining a neutral spine. Press through your palms to return to a strong plank position.','https://www.youtube.com/watch?v=NyKW3envo4M','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(4,NULL,'kettlebell-deadlift','Kettlebell Deadlift','strength','Posterior chain','Kettlebell','reps_weight','Place a kettlebell on the floor between your feet and stand with feet hip-width apart. Hinge at your hips with a flat back and reach down to grip the handle. Brace your core before lifting. Drive through your heels to extend your hips and stand tall. Push your hips back and lower the kettlebell with control to return to the floor.','https://www.youtube.com/watch?v=8C4H0Gq0VRY','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(5,NULL,'alternating-kettlebell-overhead-press','Alternating Kettlebell Overhead Press','strength','Shoulders','Kettlebell','reps_weight','Choose an appropriate kettlebell and hold it at shoulder height with your wrist neutral and elbow stacked under the weight. Stand tall with feet shoulder-width apart and core braced. Press the kettlebell straight overhead until your arm is fully extended. Lower it back to shoulder height with control and repeat on the opposite side.','https://www.youtube.com/watch?v=z_26WzNe4dU','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(6,NULL,'dumbbell-bent-over-row','Dumbbell Bent Over Row','strength','Back','Dumbbells','reps_weight','Select two dumbbells and hinge forward at your hips with feet hip-width apart and back flat. Let the dumbbells hang directly below your shoulders with your core engaged. Pull the weights toward your ribcage, squeezing your shoulder blades together. Lower the dumbbells slowly back to the starting position.','https://www.youtube.com/watch?v=HtmoWWWbPJM','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(7,NULL,'cardio-stair-climber','Cardio - Stair Climber','cardio','Legs','Stair climber','duration','Maintain upright posture and steady breathing. Drive through your full foot on each step.',NULL,'https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(8,NULL,'leg-press-machine','Leg Press Machine','strength','Legs','Machine','reps_weight','Adjust the seat so your knees are bent at about 90 degrees when your feet are on the platform. Sit back with your spine against the pad and feet shoulder-width apart. Begin by lowering the platform under control. Press through your heels to extend your legs, stopping just short of locking out your knees.','https://www.youtube.com/watch?v=65dYEHxt3YM','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(9,NULL,'seated-chest-press-machine','Seated Chest Press Machine','strength','Chest','Machine','reps_weight','Adjust the seat so the handles align with the middle of your chest. Sit upright with your back supported and feet flat on the floor. Start with elbows bent and hands gripping the handles. Press forward until your arms are extended, then return slowly to the starting position.','https://www.youtube.com/watch?v=rumgdDnsO0A','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(10,NULL,'seated-row-machine','Seated Row Machine','strength','Back','Machine','reps_weight','Adjust the seat and chest pad so the handles are comfortably within reach. Sit tall with your chest supported and feet planted firmly. Begin with arms fully extended. Pull the handles toward your torso, squeezing your shoulder blades together. Extend your arms slowly to return to start.','https://www.youtube.com/watch?v=ZS0cMdseyuM','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(11,NULL,'glute-drive-machine','Glute Drive Machine','strength','Glutes','Machine','reps_weight','Adjust the back pad and position the hip pad comfortably across your hips. Place your feet hip-width apart with knees bent and back supported against the pad. Brace your core and keep your chin tucked to maintain a neutral spine. Drive through your heels to lift your hips upward, fully extending your hips and squeezing your glutes at the top. Lower your hips back down under control to return to the starting position.','https://www.youtube.com/watch?v=fa9Eb1IGUvs','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(12,NULL,'seated-shoulder-press-machine','Seated Shoulder Press','strength','Shoulders','Machine','reps_weight','Set the seat height so the handles begin at shoulder level. Sit upright with your back supported and feet flat. Grip the handles and press overhead until your arms are fully extended. Lower the handles back to shoulder height with control.','https://www.youtube.com/watch?v=XOmDApzpykU','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(13,NULL,'seated-lat-pulldown','Seated Lat Pulldown','strength','Back','Machine','reps_weight','Adjust the thigh pad to secure your legs and select an appropriate weight. Sit tall with a slight lean back and grip the bar wider than shoulder-width. Start with arms fully extended overhead. Pull the bar down toward your upper chest while keeping your chest lifted. Slowly extend your arms to return to the starting position.','https://www.youtube.com/watch?v=JjvFHDcIWts','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(14,NULL,'cardio-incline-treadmill-walk','Cardio - Incline Treadmill Walk','cardio','Legs','Treadmill','distance_duration',NULL,NULL,'https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(15,NULL,'studio-red-class','Studio Red Class','class',NULL,NULL,'class','Check out your Studio Red class schedule for available times.',NULL,'https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(16,NULL,'dumbbell-reverse-lunge','Dumbbell Reverse Lunges','strength','Legs','Dumbbells','reps_weight','Select a pair of dumbbells and hold them at your sides. Stand tall with feet hip-width apart. Step one foot backward to begin the movement. Lower until both knees reach about 90 degrees while keeping your chest upright. Drive through your front heel to return to standing and repeat on the other side.','https://www.youtube.com/watch?v=zGHbpUvuqUY','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(17,NULL,'dumbbell-single-arm-row-on-bench','Dumbbell Single-Arm Row on Bench','strength','Back','Dumbbell and bench','reps_weight','With one knee and hand on a bench, row the dumbbell toward your hip. Lower slowly and repeat on the opposite side.','https://www.youtube.com/watch?v=HtmoWWWbPJM','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(18,NULL,'single-leg-glute-bridge','Single-Leg Glute Bridge','strength','Glutes','Mat','reps_bodyweight','Lie on your back on a mat with one foot planted and the other leg extended. Keep your arms at your sides and core engaged. Press through the heel of the planted foot to lift your hips upward until your body forms a straight line from shoulders to knee. Lower your hips slowly back to the floor and repeat before switching sides.','https://www.youtube.com/watch?v=Y0SXy73T36M','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(19,NULL,'standing-kettlebell-shoulder-press','Standing Kettlebell Shoulder Press','strength','Shoulders','Kettlebell','reps_weight','Select a kettlebell and hold it at shoulder height in the racked position with your wrist neutral and elbow under the weight. Stand with feet shoulder-width apart and core braced. Press the kettlebell straight overhead until your arm is fully extended. Lower it back to shoulder height with control before switching sides if needed.','https://www.youtube.com/watch?v=z_26WzNe4dU','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(20,NULL,'trx-assisted-pull-up','TRX Assisted Pull-Up','strength','Back','TRX','reps_bodyweight','Shorten the TRX straps and adjust your body angle to control the level of assistance. Hold the handles with arms extended and body in a straight line. Engage your core and pull your chest toward the handles. Slowly extend your arms to return to the starting position.','https://www.youtube.com/watch?v=nBP1OffNl5o','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(21,NULL,'hack-squat-machine','Hack Squat Machine','strength','Legs','Machine','reps_weight','Position your shoulders under the pads and place your feet shoulder-width apart on the platform. Stand tall with your back against the pad and unlock the safety handles. Lower into a squat under control until your knees reach about 90 degrees. Press through your heels to return to standing.','https://www.youtube.com/watch?v=8Ln6VO8gsfI','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(22,NULL,'diamond-push-up','Diamond Push-Up','strength','Triceps','Bodyweight','reps_bodyweight','Place your hands close together beneath your chest, forming a diamond shape with your fingers (elevate your hands if needed). Position your body in a straight plank with core engaged. Lower your chest toward your hands while keeping elbows close to your sides. Press back up to return to plank.','https://www.youtube.com/watch?v=sZwppbIG6Xo','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(23,NULL,'standing-cable-row','Standing Cable Row','strength','Back','Cable','reps_weight','Set the cable attachment at chest height and choose an appropriate weight. Stand tall with a slight bend in your knees and a neutral spine. Begin with arms fully extended. Pull the handle toward your torso while squeezing your shoulder blades together. Extend your arms slowly to return to the starting position.','https://www.youtube.com/watch?v=Ba0lZDdZnLw','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
INSERT INTO "exercise_library" ("id","owner","slug","name","category","primary_muscle_group","equipment_type","measurement_type","description","video_url","source_url","is_system","is_active","created_at","updated_at") VALUES(24,NULL,'dumbbell-lateral-raise','Dumbbell Lateral Raise','strength','Shoulders','Dumbbells','reps_weight','Select light-to-moderate dumbbells and stand with feet hip-width apart. Hold the weights at your sides with a slight bend in your elbows and core engaged. Raise your arms out to the sides until they reach shoulder height. Lower the dumbbells slowly back to your sides.','https://www.youtube.com/watch?v=T6I0ggj4ZIk','https://vasafitness.com/workout-general/',1,1,'2026-08-28 16:48:44','2026-08-28 16:48:44');
CREATE TABLE `workout_programs` (
  `id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
  `owner` text,
  `slug` text NOT NULL,
  `name` text NOT NULL,
  `description` text,
  `source_url` text,
  `total_weeks` integer NOT NULL DEFAULT 4,
  `is_system` integer NOT NULL DEFAULT 0,
  `is_active` integer NOT NULL DEFAULT 1,
  `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CHECK (`total_weeks` > 0)
);
INSERT INTO "workout_programs" ("id","owner","slug","name","description","source_url","total_weeks","is_system","is_active","created_at","updated_at") VALUES(1,NULL,'vasa-4-week','VASA Four-Week Fitness Program','VASA''s published four-week plan: three workouts a week — functional/free weight, machines, and a Studio Red class. After Week 4 you start a fresh four-week cycle at Week 1.','https://vasafitness.com/workout-general/',4,1,1,'2026-08-28 16:48:43','2026-08-28 16:48:43');
CREATE TABLE `workout_program_weeks` (
  `id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
  `program_id` integer NOT NULL REFERENCES `workout_programs`(`id`) ON DELETE CASCADE,
  `week_number` integer NOT NULL,
  `name` text,
  `description` text,
  `display_order` integer NOT NULL DEFAULT 0,
  CHECK (`week_number` > 0)
);
INSERT INTO "workout_program_weeks" ("id","program_id","week_number","name","description","display_order") VALUES(1,1,1,'Week 1',NULL,1);
